-- =====================================================================================
-- WIKIPEDIA-CRAWLER-023 : couverture Wikipedia des oeuvres sources (famille sourcework, 224)
--
-- LECTURE SEULE. A lancer avant le premier passage de la famille, puis apres, pour voir
-- ce qu'elle a apporte, et une troisieme fois apres le processus 71 de tmdb-movie-preprocess.
--
--   1. Combien de lignes la famille selectionne : avec la chaine d'exclusion (le passage
--      normal du crawler, process 224) et sans elle (--no-exclusions). L'ecart est la part
--      deja possedee par une famille anterieure (201 movie, 203 item...), dont le texte et
--      l'image sont ecrits sous le meme ID_WIKIDATA : rien n'y manque si ce crawl est frais.
--   2. La couverture : pages trouvees, sections, image principale par langue dans
--      T_WC_WIKIPEDIA_PAGE_LANG, et ce que le processus 71 en a deja copie dans
--      T_WC_T2S_SOURCE_WORK.
--   3. Le detail de trois oeuvres de reference : Heart of Darkness (Q129778), Dracula
--      (Q41542), Nineteen Eighty-Four (Q208460). Critere d'acceptation du ticket : Heart
--      of Darkness a MAIN_IMAGE_URL et des sections en en et fr, puis, apres le 71,
--      WIKIPEDIA_MAIN_IMAGE_URL et _FR remplis.
-- =====================================================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

SELECT '1. Rows selected by the sourcework family' AS SECTION;

SELECT
  (SELECT COUNT(*) FROM T_WC_T2S_SOURCE_WORK) AS ALL_ROWS,
  (SELECT COUNT(*) FROM T_WC_T2S_SOURCE_WORK WHERE COALESCE(DELETED, 0) <> 0) AS DELETED_ROWS,
  (SELECT COUNT(*) FROM T_WC_T2S_SOURCE_WORK
    WHERE COALESCE(DELETED, 0) = 0 AND SOURCE_WORK_TYPE = 'screen'
      AND (ID_MOVIE IS NOT NULL OR ID_SERIE IS NOT NULL)) AS SCREEN_WITH_T2S_SHEET_EXCLUDED,
  (SELECT COUNT(*) FROM T_WC_T2S_SOURCE_WORK
    WHERE ID_WIKIDATA REGEXP '^Q[0-9]+$' AND COALESCE(DELETED, 0) = 0 AND NOT (COALESCE(SOURCE_WORK_TYPE, '') = 'screen' AND (ID_MOVIE IS NOT NULL OR ID_SERIE IS NOT NULL))) AS SELECTED_NO_EXCLUSIONS,
  (SELECT COUNT(*) FROM (SELECT DISTINCT T_WC_T2S_SOURCE_WORK.ID_SOURCE_WORK AS id, ID_WIKIDATA FROM T_WC_T2S_SOURCE_WORK WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '' AND ID_WIKIDATA REGEXP '^Q[0-9]+$' AND COALESCE(DELETED, 0) = 0 AND NOT (COALESCE(SOURCE_WORK_TYPE, '') = 'screen' AND (ID_MOVIE IS NOT NULL OR ID_SERIE IS NOT NULL)) AND ID_WIKIDATA NOT IN (SELECT ID_WIKIDATA FROM T_WC_WIKIDATA_MOVIE_V1) AND ID_WIKIDATA NOT IN (SELECT ID_WIKIDATA FROM T_WC_WIKIDATA_PERSON_V1) AND ID_WIKIDATA NOT IN (SELECT ID_WIKIDATA FROM T_WC_WIKIDATA_ITEM_V1) AND ID_WIKIDATA NOT IN (SELECT ID_WIKIDATA FROM T_WC_WIKIDATA_SERIE_V1) AND ID_WIKIDATA NOT IN (SELECT ID_WIKIDATA FROM T_WC_WIKIDATA_CHARACTER_V1) AND ID_WIKIDATA NOT IN (SELECT 'Q1204187' AS ID_WIKIDATA FROM DUAL) AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_LIST WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_MOVEMENT WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_COLLECTION WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_GROUP WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_DEATH WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_AWARD WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_NOMINATION WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_TOPIC WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_T2S_TECHNICAL WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_CHARACTER WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_COLLECTION WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_EPISODE WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_KEYWORD WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '') AND ID_WIKIDATA NOT IN (SELECT DISTINCT ID_WIKIDATA FROM T_WC_TMDB_SEASON WHERE ID_WIKIDATA IS NOT NULL AND ID_WIKIDATA <> '')) x) AS SELECTED_WITH_CHAIN;

SELECT '2. Wikipedia coverage of the source works the family keeps' AS SECTION;

SELECT
  COUNT(*) AS SOURCE_WORKS,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG pl WHERE pl.ID_WIKIDATA = sw.ID_WIKIDATA AND pl.LANG = 'en' AND COALESCE(pl.WIKIPEDIA_PAGE_TITLE, '') <> '')) AS PAGE_EN,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG pl WHERE pl.ID_WIKIDATA = sw.ID_WIKIDATA AND pl.LANG = 'fr' AND COALESCE(pl.WIKIPEDIA_PAGE_TITLE, '') <> '')) AS PAGE_FR,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG_SECTION s WHERE s.ID_WIKIDATA = sw.ID_WIKIDATA AND s.LANG = 'en')) AS SECTIONS_EN,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG_SECTION s WHERE s.ID_WIKIDATA = sw.ID_WIKIDATA AND s.LANG = 'fr')) AS SECTIONS_FR,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG pl WHERE pl.ID_WIKIDATA = sw.ID_WIKIDATA AND pl.LANG = 'en' AND COALESCE(pl.MAIN_IMAGE_URL, '') <> '')) AS MAIN_IMAGE_EN,
  SUM(EXISTS (SELECT 1 FROM T_WC_WIKIPEDIA_PAGE_LANG pl WHERE pl.ID_WIKIDATA = sw.ID_WIKIDATA AND pl.LANG = 'fr' AND COALESCE(pl.MAIN_IMAGE_URL, '') <> '')) AS MAIN_IMAGE_FR,
  SUM(COALESCE(sw.WIKIPEDIA_MAIN_IMAGE_URL, '') <> '') AS T2S_IMAGE_EN,
  SUM(COALESCE(sw.WIKIPEDIA_MAIN_IMAGE_URL_FR, '') <> '') AS T2S_IMAGE_FR
FROM T_WC_T2S_SOURCE_WORK sw
WHERE sw.ID_WIKIDATA REGEXP '^Q[0-9]+$'
  AND COALESCE(sw.DELETED, 0) = 0
  AND NOT (COALESCE(sw.SOURCE_WORK_TYPE, '') = 'screen' AND (sw.ID_MOVIE IS NOT NULL OR sw.ID_SERIE IS NOT NULL));

SELECT '3. Reference works, one row per language' AS SECTION;

SELECT sw.ID_SOURCE_WORK, sw.ID_WIKIDATA, sw.SOURCE_WORK_NAME, sw.SOURCE_WORK_TYPE,
       sw.ID_MOVIE, sw.ID_SERIE, pl.LANG, pl.ITEM_TYPE, pl.WIKIPEDIA_PAGE_TITLE,
       pl.LAST_SUCCESS_AT, pl.MAIN_IMAGE_URL,
       (SELECT COUNT(*) FROM T_WC_WIKIPEDIA_PAGE_LANG_SECTION s
         WHERE s.ID_WIKIDATA = sw.ID_WIKIDATA AND s.LANG = pl.LANG) AS SECTION_ROWS,
       CASE pl.LANG WHEN 'en' THEN sw.WIKIPEDIA_MAIN_IMAGE_URL ELSE sw.WIKIPEDIA_MAIN_IMAGE_URL_FR END AS T2S_IMAGE
FROM T_WC_T2S_SOURCE_WORK sw
LEFT JOIN T_WC_WIKIPEDIA_PAGE_LANG pl ON pl.ID_WIKIDATA = sw.ID_WIKIDATA
WHERE sw.ID_WIKIDATA IN ('Q129778', 'Q41542', 'Q208460')
ORDER BY sw.ID_WIKIDATA, pl.LANG;
